# v15.14: trade fee paid in another asset, interest destination (Earn/Spot), tax per item, collapsible currency filters
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'; res=[]
def ok(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':390,'height':844},device_scale_factor=2,service_workers='block'); pg=ctx.new_page(); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached')
    pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000); pg.click('#setup .btn'); pg.wait_for_timeout(900)
    pg.evaluate("""async()=>{const c=await import('/js/core.js');c.commit(d=>{
      const A=(id,cur,open,w)=>d.accounts.push(c.stamp({id,name:'Bitget '+cur,wallet:w||'Spot',cur,type:'crypto',assetType:'crypto',exchange:'Bitget',open,include:false,archived:false,invtab:true}));
      A('u1','USDT',1000);A('b1','BTC',0.1);A('g1','BGB',50);A('e1','USDT',200,'Earn');d.accounts.find(a=>a.id==='e1').apy=5;
      d.settings.tickers=d.settings.tickers||{};});}""")
    # ---- 1. fee paid with another asset ----
    pg.evaluate("(async()=>{const m=await import('/js/trades.js');m.openTrade({asset:'b1',side:'buy'})})()"); pg.wait_for_selector('#tr'); pg.wait_for_timeout(300)
    pg.click('[data-fm=fixed]'); pg.wait_for_timeout(150)
    labs=pg.evaluate("[...document.querySelectorAll('[data-resp]')].map(x=>x.textContent.trim())")
    ok('three responsibility options %s'%labs, labs==['Taken from Maker','Taken from Taker','Other Asset'])
    ok('asset picker hidden until Other Asset', not pg.is_visible('#f-feeacct'))
    pg.click('[data-resp=other]'); pg.wait_for_timeout(200)
    ok('Other Asset shows the picker and is pressed', pg.is_visible('#f-feeacct') and pg.get_attribute('[data-resp=other]','aria-pressed')=='true' and pg.get_attribute('[data-resp=maker]','aria-pressed')=='false')
    opts=pg.evaluate("[...document.querySelectorAll('#tr [name=feeAcct] option')].map(o=>o.value)")
    ok('picker lists the platform assets %s'%opts, 'g1' in opts and 'u1' in opts)
    pg.select_option('#tr [name=feeAcct]','g1'); pg.wait_for_timeout(150)
    ok('fee label names BGB and the balance is shown', 'BGB' in pg.inner_text('#l-fee') and '50' in pg.inner_text('#feeacct-hint'))
    pg.fill('#tr [name=qty]','0.01'); pg.dispatch_event('#tr [name=qty]','input'); pg.fill('#tr [name=total]','600'); pg.dispatch_event('#tr [name=total]','input'); pg.fill('#tr [name=fee]','2'); pg.dispatch_event('#tr [name=fee]','input'); pg.wait_for_timeout(150)
    pg.select_option('#tr [name=cash]','u1'); pg.wait_for_timeout(100)
    pg.evaluate("document.querySelector('#tr .btnrow .btn:not(.ghost)').click()"); pg.wait_for_timeout(800)
    r=pg.evaluate("""(async()=>{const c=await import('/js/core.js');const d=c.get(),bal=c.balances(d),t=d.txs.find(x=>!x.deleted&&x.trade&&x.trade.asset==='b1'),k=d.txs.find(x=>!x.deleted&&x.tradeOf===(t&&t.id));return {bgb:bal.get('g1'),usdt:bal.get('u1'),btc:bal.get('b1'),other:t&&t.trade.feeOther,fee:k&&[k.acct,k.amount,k.cur]}})()""")
    ok('BGB lost 2, USDT lost 600, BTC gained 0.01 %s'%r, r['bgb']==48 and r['usdt']==400 and abs(r['btc']-0.11)<1e-9 and r['other']=='g1' and r['fee']==['g1',2,'BGB'])
    pg.evaluate("(async()=>{const m=await import('/js/trades.js');const c=await import('/js/core.js');const t=c.get().txs.find(x=>!x.deleted&&x.trade&&x.trade.asset==='b1');m.openTrade({edit:t.id})})()"); pg.wait_for_selector('#tr'); pg.wait_for_timeout(400)
    ok('edit: Other Asset and BGB come back', pg.is_visible('#f-feeacct') and pg.input_value('#tr [name=feeAcct]')=='g1' and pg.input_value('#tr [name=fee]')=='2')
    pg.evaluate("document.querySelectorAll('.scrim').forEach(e=>e.remove())")
    # ---- 2. interest destination ----
    pg.evaluate("(async()=>{const m=await import('/js/accpage.js');m.openAccount('e1')})()"); pg.wait_for_selector('#acct-form'); pg.wait_for_timeout(300)
    pg.fill('[name=apy]','5'); pg.wait_for_timeout(150)
    ok('destination selector is shown for a platform account', pg.locator('[name=interestTo]').count()==1 and pg.is_visible('#f-intto'))
    pg.select_option('[name=interestTo]','spot')
    pg.click('#acct-form button:text-is("Save")'); pg.wait_for_timeout(800)
    ok('saved as Spot', pg.evaluate("window.sukli.get().accounts.find(a=>a.id==='e1').interestTo")=='spot')
    r=pg.evaluate("""(async()=>{const c=await import('/js/core.js'),f=await import('/js/finance.js');const iso=n=>{const d=new Date();d.setDate(d.getDate()-n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
      c.commit(d=>{const a=d.accounts.find(x=>x.id==='e1');a.interestFrom=iso(4);a.taxPct=0;a.compound='daily';f.postInterest(d,iso(1));});
      const d=c.get(),l=d.txs.filter(t=>!t.deleted&&String(t.id).startsWith('int-e1-'));return {n:l.length,accts:[...new Set(l.map(t=>t.acct))],earnBal:c.balances(d).get('e1')}})()""")
    ok('interest entries go to Spot (u1), not the Earn account %s'%r, r['n']>=3 and r['accts']==['u1'] and r['earnBal']==200)
    pg.evaluate("document.querySelectorAll('.scrim').forEach(e=>e.remove())")
    pg.evaluate("(async()=>{const m=await import('/js/accpage.js');m.openAccountDetail('e1')})()"); pg.wait_for_timeout(700)
    ok('account page says it goes to Spot and counts what was earned', 'Spot account' in pg.inner_text('#ad') and 'Earned so far' in pg.inner_text('#ad'))
    pg.evaluate("document.querySelectorAll('.scrim').forEach(e=>e.remove())")
    r=pg.evaluate("""(async()=>{const c=await import('/js/core.js'),f=await import('/js/finance.js');c.commit(d=>{d.accounts.find(x=>x.id==='e1').interestTo='';f.postInterest(d,'2099-01-01');});const d=c.get();return d.txs.filter(t=>!t.deleted&&String(t.id).startsWith('int-e1-')&&t.acct==='e1').length})()""")
    ok('switching back to Earn credits new interest to the Earn account %s'%r, r>0)
    # ---- 3. tax per item ----
    pg.click('.fab'); pg.wait_for_selector('#entry'); pg.wait_for_timeout(200)
    pg.evaluate("document.querySelector('[data-e=items-on]').click()"); pg.wait_for_selector('.itembox'); pg.wait_for_timeout(200)
    for i,(n,a) in enumerate([('Bento','500'),('Magazine','1000'),('Tape','100')]):
        if i: pg.evaluate("document.querySelector('[data-e=item-add]').click()"); pg.wait_for_timeout(150)
        pg.locator('.item .in-n').nth(i).fill(n); pg.locator('.item .in-a').nth(i).fill(a); pg.locator('.item .in-a').nth(i).dispatch_event('input')
    pg.evaluate("document.querySelector('[data-e=item-tax][data-v=\"0\"]').click()"); pg.wait_for_selector('.itax'); pg.evaluate("document.querySelector('[data-e=item-tax-set][data-v=\"0:8\"]').click()"); pg.wait_for_timeout(120)
    pg.evaluate("document.querySelector('[data-e=item-tax][data-v=\"1\"]').click()"); pg.wait_for_timeout(120)
    ok('toggle starts at 10 percent', pg.locator('.item').nth(1).locator('.in-t').input_value()=='10')
    ok('8 percent on 500 = 40 shown on the line %s'%pg.locator('.iline').nth(0).inner_text(), '40' in pg.locator('.iline').nth(0).inner_text() and '8%' in pg.locator('.iline').nth(0).inner_text())
    ok('10 percent on 1000 = 100', '100' in pg.locator('.iline').nth(1).inner_text())
    pg.fill('.item >> nth=1 >> .in-t','8'); pg.dispatch_event('.item >> nth=1 >> .in-t','input'); pg.wait_for_timeout(100)
    ok('typing 8 lights the 8% button and gives 80', '80' in pg.locator('.iline').nth(1).inner_text() and pg.locator('.item').nth(1).locator('.itax .seg button.on').inner_text()=='8%')
    pg.fill('.item >> nth=1 >> .in-t','10'); pg.dispatch_event('.item >> nth=1 >> .in-t','input')
    pg.evaluate("document.querySelector('[data-e=tax-toggle]').click()"); pg.wait_for_selector('#f-taxv'); pg.evaluate("document.querySelector('[data-e=tax-set][data-v=\"10\"]').click()"); pg.wait_for_timeout(150)
    ok('whole-bill tax only applies to the item with no tax of its own (10 on 100) %s'%pg.inner_text('#taxcalc'), 'Tax' in pg.inner_text('#taxcalc') and '10' in pg.inner_text('#taxcalc') and '100' in pg.inner_text('#taxcalc'))
    pg.fill('#f-amount','1750'); pg.dispatch_event('#f-amount','input'); pg.wait_for_timeout(150)
    ok('items 1600 + tax 40+100+10 = 1750 add up %s'%pg.inner_text('#itemleft'), 'add up' in pg.inner_text('#itemleft'))
    pg.fill('#f-what','Konbini run'); pg.dispatch_event('#f-what','input'); pg.evaluate("document.querySelector('[data-e=save]').click()"); pg.wait_for_timeout(800)
    r=pg.evaluate("(async()=>{const c=await import('/js/core.js');const t=c.get().txs.find(x=>!x.deleted&&(x.items||[]).some(i=>i.n==='Konbini run'||i.n==='Magazine'));return t&&{amt:t.amount,items:t.items}})()")
    ok('saved: tp on the first two items, one Tax line of 150 %s'%r, r and r['amt']==1750 and r['items'][0]['tp']==8 and r['items'][1]['tp']==10 and 'tp' not in r['items'][2] and r['items'][3]['tax'] and r['items'][3]['amt']==150)
    pg.evaluate("(async()=>{const m=await import('/js/entry.js');const c=await import('/js/core.js');const t=c.get().txs.find(x=>!x.deleted&&(x.items||[]).some(i=>i.n==='Konbini run'||i.n==='Magazine'));m.openEntry({id:t.id})})()"); pg.wait_for_selector('.itembox',timeout=4000); pg.wait_for_timeout(300)
    ok('reopened: per-item rates and whole-bill 10 are back, still adds up', pg.locator('.item').nth(0).locator('.in-t').input_value()=='8' and pg.locator('.item').nth(1).locator('.in-t').input_value()=='10' and pg.locator('.item').nth(2).locator('.in-t').count()==0 and pg.input_value('#f-taxv')=='10' and 'add up' in pg.inner_text('#itemleft'))
    pg.evaluate("document.querySelectorAll('.scrim').forEach(e=>e.remove())")
    # ---- 4. collapsible currency filters ----
    pg.evaluate("localStorage.removeItem('sukli-acchips-fold')")
    pg.click('.fab'); pg.wait_for_selector('#entry'); pg.wait_for_timeout(200)
    pg.click('#acctrow button, #acctrow .row, #acctrow [data-e=acct]'); pg.wait_for_selector('#acq'); pg.wait_for_timeout(200)
    ok('filters open by default', pg.is_visible('#acchips') and pg.get_attribute('[data-chipfold]','aria-expanded')=='true')
    h1=pg.evaluate("document.querySelector('#aclist').getBoundingClientRect().top")
    pg.click('[data-chipfold]'); pg.wait_for_timeout(150)
    h2=pg.evaluate("document.querySelector('#aclist').getBoundingClientRect().top")
    ok('collapsing hides the chips and gives the list more room (%s -> %s)'%(h1,h2), not pg.is_visible('#acchips') and h2<h1 and pg.get_attribute('[data-chipfold]','aria-expanded')=='false')
    ok('the button still says which currency is active', 'Currency:' in pg.inner_text('[data-chipfold]'))
    pg.click('[data-chipfold]'); pg.wait_for_timeout(100); pg.click('[data-chip]:not([data-chip=""]) >> nth=0'); pg.wait_for_timeout(150)
    cu=pg.evaluate("document.querySelector('[data-chip].on').dataset.chip")
    pg.click('[data-chipfold]'); pg.wait_for_timeout(100)
    ok('a filter stays active while collapsed (%s)'%cu, cu and cu in pg.inner_text('[data-chipfold]'))
    pg.evaluate("document.querySelectorAll('.scrim').forEach(e=>e.remove())"); pg.click('.fab') if pg.locator('#entry').count()==0 else None
    pg.wait_for_selector('#entry'); pg.click('#acctrow button, #acctrow .row, #acctrow [data-e=acct]'); pg.wait_for_selector('#acq')
    ok('collapsed state is remembered next time', not pg.is_visible('#acchips'))
    ok('no errors %s'%[e for e in errs if 'Tunnel' not in e], not [e for e in errs if 'Tunnel' not in e])
print('fails',res.count(False))
